     3	import {readFileSync} from 'node:fs';
     4	import {sampleRoad,advanceRun,chaseTargets} from './route-motion.mjs';
     5	const data=JSON.parse(readFileSync(new URL('../scenery/route.json',import.meta.url)));
     6	const road=data.mainRoute;
     7	const near=(a,b,e=1e-5)=>assert.ok(Math.abs(a-b)<e,`${a} != ${b}`);
