    27	});
    28	test('distance and gait clamp to route endpoint without extra foot cycling',()=>{
    29	  const s=advanceRun({s:road.length-.1,speed:4,phase:.1,braked:false},1,{runSpeed:4,routeLength:road.length});near(s.s,road.length);near(s.speed,0);near(s.distanceMoved,.1);near(advanceRun(s,1,{runSpeed:4,routeLength:road.length}).phase,s.phase);
    30	});
    31	test('branch endpoints coincide with main route and comparable progress',()=>{
    32	 for(const b of data.branches){for(const [s,m] of [[0,b.startS],[b.points.at(-1).s,b.endS]]){const p=sampleRoad(b,s),q=sampleRoad(road,m);p.position.forEach((v,i)=>near(v,q.position[i],0.002));near(p.mainS,m,0.002);}}
    33	});
    34	test('camera aims forward along the continuous route with finite positions',()=>{
    35	 for(let s=0;s<road.length;s+=2){const c=chaseTargets(road,s);assert.ok(c.position.every(Number.isFinite));assert.ok(c.target.every(Number.isFinite));assert.ok(c.target[2]>c.position[2]);}
    36	});

  1	/** Engine-independent Pointer Events input. Coordinates and thresholds use CSS pixels. */
  2	export const DEFAULTS = Object.freeze({
  3	  swipeWidthRatio: 0.08, swipeMin: 24, swipeMax: 72,
  4	  axisDominance: 1.2, tapSlop: 10, tapDuration: 200,
  5	  doubleTapInterval: 320, doubleTapDistance: 24,
  6	});
  7	
  8	export const INTENTS = Object.freeze({
  9	  left: Object.freeze({ type: 'steer', direction: -1 }),
 10	  right: Object.freeze({ type: 'steer', direction: 1 }),
 11	  jump: Object.freeze({ type: 'jump' }),
 12	  togglePlayerBrake: Object.freeze({ type: 'toggle-player-brake' }),
 13	  toggleGlobalPause: Object.freeze({ type: 'toggle-global-pause' }),
 14	});
 15	
 16	export function swipeThreshold(viewportWidth, options = {}) {
 17	  const c = { ...DEFAULTS, ...options };
 18	  const width = Number.isFinite(viewportWidth) && viewportWidth > 0 ? viewportWidth : 320;
 19	  return Math.min(c.swipeMax, Math.max(c.swipeMin, width * c.swipeWidthRatio));
 20	}
 21	
 22	/** Pure classification: returns tap/left/right/jump/reserved/none. */
 23	export function classifyGesture({ dx, dy, duration, maxDistance, viewportWidth }, options = {}) {
 24	  const c = { ...DEFAULTS, ...options };
 25	  const travel = Math.max(maxDistance, Math.hypot(dx, dy));
 26	  if (duration >= 0 && duration <= c.tapDuration && travel <= c.tapSlop) return 'tap';
 27	  const threshold = swipeThreshold(viewportWidth, c);
 28	  const x = Math.abs(dx), y = Math.abs(dy);
 29	  if (x >= threshold && x >= y * c.axisDominance) return dx < 0 ? 'left' : 'right';
 30	  if (y >= threshold && y >= x * c.axisDominance) return dy < 0 ? 'jump' : 'reserved';
 31	  return 'none';
 32	}
 33	
 34	/** Stateful but DOM-free. Every event supplies {pointerId,x,y,time,viewportWidth};
 35	 * down additionally accepts ignored. Methods return arrays of immutable intents.
 36	 * time is milliseconds from one monotonic clock. One completed gesture => <=1 intent.
 37	 */
 38	export function createGestureMachine(options = {}) {
 39	  const c = { ...DEFAULTS, ...options };
 40	  const pointers = new Set();
 41	  let stroke = null, firstTap = null, blocked = false, lastTime = -Infinity;
 42	  const clock = value => {
 43	    if (!Number.isFinite(value)) throw new TypeError('A finite monotonic time is required');
 44	    lastTime = Math.max(lastTime, value);
 45	    return lastTime;
 46	  };
 47	  const update = event => {
 48	    if (!stroke || stroke.id !== event.pointerId) return;
 49	    stroke.x = event.x; stroke.y = event.y;
 50	    stroke.maxDistance = Math.max(stroke.maxDistance,
 51	      Math.hypot(event.x - stroke.startX, event.y - stroke.startY));
 52	  };
 53	  return {
 54	    down(event) {
 55	      const time = clock(event.time);
 56	      if (pointers.has(event.pointerId)) return [];
 57	      pointers.add(event.pointerId);
 58	      if (event.ignored || pointers.size > 1) {
 59	        stroke = firstTap = null; blocked = true;
 60	        return [];
 61	      }
 62	      if (blocked) return [];
 63	      stroke = { id: event.pointerId, startX: event.x, startY: event.y,
 64	        x: event.x, y: event.y, startTime: time, maxDistance: 0,
 65	        viewportWidth: event.viewportWidth };
 66	      return [];
 67	    },
 68	    move(event) {
 69	      clock(event.time); update(event); return [];
 70	    },
 71	    up(event) {
 72	      const time = clock(event.time);
 73	      if (!pointers.has(event.pointerId)) return [];
 74	      update(event);
 75	      const completed = stroke?.id === event.pointerId ? stroke : null;
 76	      pointers.delete(event.pointerId);
 77	      if (completed) stroke = null;
 78	      if (pointers.size === 0) blocked = false;
 79	      if (!completed) return [];
 80	      const kind = classifyGesture({ dx: completed.x - completed.startX,
 81	        dy: completed.y - completed.startY, duration: time - completed.startTime,
 82	        maxDistance: completed.maxDistance, viewportWidth: completed.viewportWidth }, c);
 83	      if (kind === 'tap') {
 84	        if (firstTap && time - firstTap.time <= c.doubleTapInterval &&
 85	            Math.hypot(completed.startX - firstTap.x, completed.startY - firstTap.y) <= c.doubleTapDistance) {
 86	          firstTap = null;
 87	          return [INTENTS.togglePlayerBrake];
 88	        }
 89	        firstTap = { time, x: completed.startX, y: completed.startY };
 90	        return [];
 91	      }
 92	      firstTap = null;
 93	      return INTENTS[kind] ? [INTENTS[kind]] : [];
 94	    },
 95	    cancel(pointerId, { retainPointer = false } = {}) {
 96	      if (!pointers.has(pointerId)) return [];
 97	      if (!retainPointer) pointers.delete(pointerId);
 98	      stroke = firstTap = null;
 99	      blocked = pointers.size > 0;
100	      return [];
101	    },
102	    reset() {
103	      pointers.clear(); stroke = firstTap = null; blocked = false;
104	      return [];
105	    },
106	  };
107	}
